import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'

        */
        var cleaned: String = ""
        var i: Int32 = 0
        let s = this.expr
        while (i < s.length()) {
            let ch = s.substring(i, i + 1)
            let idxL = this.left_brackets.indexOf(ch)
            let idxR = this.right_brackets.indexOf(ch)
            if (idxL != -1 || idxR != -1) {
                cleaned = cleaned + ch
            }
            i = i + 1
        }
        this.expr = cleaned
        this.stack.clear()
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true

        */
        // Use a cleaned local copy; do not mutate this.expr here
        var cleaned: String = ""
        var i: Int32 = 0
        let s = this.expr
        while (i < s.length()) {
            let ch = s.substring(i, i + 1)
            let idxL = this.left_brackets.indexOf(ch)
            let idxR = this.right_brackets.indexOf(ch)
            if (idxL != -1 || idxR != -1) {
                cleaned = cleaned + ch
            }
            i = i + 1
        }

        this.stack.clear()
        var j: Int32 = 0
        while (j < cleaned.length()) {
            let ch = cleaned.substring(j, j + 1)
            let idxL = this.left_brackets.indexOf(ch)
            if (idxL != -1) {
                this.stack.add(ch)
            } else {
                let idxR = this.right_brackets.indexOf(ch)
                if (idxR != -1) {
                    if (this.stack.size() == 0) {
                        return false
                    }
                    let top = this.stack.get(this.stack.size() - 1)
                    let expected = this.left_brackets.get(idxR)
                    if (top != expected) {
                        return false
                    }
                    this.stack.removeAt(this.stack.size() - 1)
                }
            }
            j = j + 1
        }
        return this.stack.size() == 0
    }
}

main() {
    let b = BalancedBrackets("a(b)c")
    println(b.check_balanced_brackets()) // true
    b.clear_expr()
    println(b.expr) // ()

    let b2 = BalancedBrackets("([{}])")
    println(b2.check_balanced_brackets()) // true

    let b3 = BalancedBrackets("(]")
    println(b3.check_balanced_brackets()) // false

    let b4 = BalancedBrackets("([)]")
    println(b4.check_balanced_brackets()) // false
}
