            if (classesOpt != Option<ArrayList<String>>.None) {
                let classes = classesOpt.unwrap()
                for (c in classes) {
                    let countOpt = counts.get(c)
                    var newCount: Int64 = 0
                    if (countOpt == Option<Int64>.None) {
                        counts.add(c, 1)
                        newCount = 1
                    } else {
                        let n = countOpt.unwrap()
                        counts.add(c, n + 1)
                        newCount = n + 1
                    }
                    if (newCount > maxCount) {
                        maxCount = newCount
                        mostPopular = c
                    }
                }
            }
        }

        return mostPopular
    }
}
