import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title: ArrayList<String> = ArrayList<String>()
        let data: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()

        // Open file for reading
        let file = openFile(file_name, mode: FileOpenMode.Read)
        let content = readString(file)
        file.close()

        // Split into lines (handle LF/CRLF)
        let lines = this.splitLines(content)
        var first = true
        for (line in lines) {
            if (first) {
                let headerRow = this.splitCsvLine(line)
                for (h in headerRow) {
                    title.add(h)
                }
                first = false
            } else {
                if (!line.isEmpty()) {
                    let row = this.splitCsvLine(line)
                    data.add(row)
                }
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        // Build CSV content
        var content = ""
        var firstRow = true
        for (row in data) {
            let line = this.joinRow(row)
            if (firstRow) {
                content = line
                firstRow = false
            } else {
                content = content + "\n" + line
            }
        }

        // Write to file
        let file = openFile(file_name, mode: FileOpenMode.Create | FileOpenMode.Truncate | FileOpenMode.Write)
        let bytes = content.toArray()
        let written = file.write(bytes)
        file.close()

        if (written >= bytes.size) {
            return 1
        } else {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        // Read existing CSV
        let (title, data) = this.read_csv(save_file_name)

        // Build new data: first row is original title, following rows are only Nth column uppercased
        let newData: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        newData.add(title)

        for (row in data) {
            var idx: Int64 = 0
            var selected: String = ""
            var found: Bool = false
            for (cell in row) {
                if (idx == N) {
                    selected = cell
                    found = true
                    break
                }
                idx = idx + 1
            }
            if (found) {
                let upper = selected.toUpperCase()
                let newRow: ArrayList<String> = ArrayList<String>()
                newRow.add(upper)
                newData.add(newRow)
            } else {
                // If the Nth column does not exist, write an empty cell
                let newRow: ArrayList<String> = ArrayList<String>()
                newRow.add("")
                newData.add(newRow)
            }
        }

        // Build new file name with "_process" suffix before extension
        let new_file_name = this.buildProcessedFileName(save_file_name)

        return this.write_csv(newData, new_file_name)
    }

    // ---- Helpers ----

    private func splitLines(text: String): ArrayList<String> {
        let lines: ArrayList<String> = ArrayList<String>()
        let buf: ArrayList<Byte> = ArrayList<Byte>()
        for (b in text.iterator()) {
            if (b == 13) { // '\r'
                continue
            } else if (b == 10) { // '\n'
                let arr = buf.toArray()
                let line = String.fromUtf8(arr)
                lines.add(line)
                buf.clear()
            } else {
                buf.add(b)
            }
        }
        if (buf.size > 0) {
            let arr = buf.toArray()
            let line = String.fromUtf8(arr)
            lines.add(line)
        }
        return lines
    }

    private func splitCsvLine(line: String): ArrayList<String> {
        let cells: ArrayList<String> = ArrayList<String>()
        let buf: ArrayList<Byte> = ArrayList<Byte>()
        var i: Int64 = 0
        for (b in line.iterator()) {
            if (b == 44) { // ','
                let arr = buf.toArray()
                let cell = String.fromUtf8(arr)
                cells.add(cell)
                buf.clear()
            } else {
                buf.add(b)
            }
            i = i + 1
        }
        // last cell
        let arr = buf.toArray()
        let cell = String.fromUtf8(arr)
        cells.add(cell)
        return cells
    }

    private func joinRow(row: ArrayList<String>): String {
        var result = ""
        var first = true
        for (cell in row) {
            if (first) {
                result = cell
                first = false
            } else {
                result = result + "," + cell
            }
        }
        return result
    }

    private func buildProcessedFileName(file_name: String): String {
        if (file_name.endsWith(".csv")) {
            // remove ".csv" and add "_process.csv"
            let prefix = this.substringBytes(file_name, 0, this.byteLength(file_name) - 4)
            return prefix + "_process.csv"
        } else {
            return file_name + "_process"
        }
    }

    private func byteLength(s: String): Int64 {
        var count: Int64 = 0
        for (_ in s.iterator()) {
            count = count + 1
        }
        return count
    }

    private func substringBytes(s: String, start: Int64, end: Int64): String {
        // Build substring using byte indices [start, end)
        let len = this.byteLength(s)
        var i: Int64 = 0
        let buf: ArrayList<Byte> = ArrayList<Byte>()
        for (b in s.iterator()) {
            if (i >= start && i < end && i < len) {
                buf.add(b)
            }
            i = i + 1
        }
        return String.fromUtf8(buf.toArray())
    }
}

