        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        let n: Int64 = data.size()
        if (n == 0) {
            return 0.00
        }
        var sum: Int64 = 0
        var i: Int64 = 0
        while (i < n) {
            sum = sum + data.get(i)
            i = i + 1
        }
        let avg: Float64 = Float64(sum) / Float64(n)
        let rounded: Float64 = round(avg * 100.0) / 100.0
        return rounded
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        let n: Int64 = data.size()
        if (n == 0) {
            return 0.00
        }
        var arr = ArrayList<Int64>(data)
        sort<Int64>(arr, stable: true)
        if ((n % 2) == 1) {
            let midVal: Int64 = arr.get(n / 2)
            return round(Float64(midVal) * 100.0) / 100.0
        } else {
            let v1: Int64 = arr.get((n / 2) - 1)
            let v2: Int64 = arr.get(n / 2)
            let med: Float64 = (Float64(v1) + Float64(v2)) / 2.0
            return round(med * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        let n: Int64 = data.size()
        if (n == 0) {
            return ArrayList<Int64>([])
        }
        var arr = ArrayList<Int64>(data)
        sort<Int64>(arr, stable: true)

        var res = ArrayList<Int64>([])
        var maxCount: Int64 = 0
        var i: Int64 = 0
        while (i < n) {
            let v: Int64 = arr.get(i)
            var count: Int64 = 1
            var j: Int64 = i + 1
            while (j < n && arr.get(j) == v) {
                count = count + 1
                j = j + 1
            }
            if (count > maxCount) {
                maxCount = count
                res = ArrayList<Int64>([])
                res.add(v)
            } else if (count == maxCount) {
                res.add(v)
            }
            i = j
        }
        return res
    }
