class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var s: Float64 = 0.0
        let n: Int32 = this.data.size()
        var i: Int32 = 0
        while (i < n) {
            s = s + this.data.get(i)
            i = i + 1
        }
        return s
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return 0.0
        }
        var m: Float64 = this.data.get(0)
        var i: Int32 = 1
        while (i < n) {
            let v: Float64 = this.data.get(i)
            if (v < m) {
                m = v
            }
            i = i + 1
        }
        return m
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return 0.0
        }
        var m: Float64 = this.data.get(0)
        var i: Int32 = 1
        while (i < n) {
            let v: Float64 = this.data.get(i)
            if (v > m) {
                m = v
            }
            i = i + 1
        }
        return m
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return 0.0
        }
        let nf: Float64 = (n as Float64)
        let mean: Float64 = this.get_sum() / nf
        var sumsq: Float64 = 0.0
        var i: Int32 = 0
        while (i < n) {
            let diff: Float64 = this.data.get(i) - mean
            sumsq = sumsq + diff * diff
            i = i + 1
        }
        let varPop: Float64 = sumsq / nf
        return round(varPop * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance: Float64 = this.get_variance()
        let sd: Float64 = sqrt(variance)
        return round(sd * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let n: Int32 = this.data.size()
        if (n <= 1) {
            return 0.0
        }
        let nf: Float64 = (n as Float64)
        let meanX: Float64 = this.get_sum() / nf
        let meanY: Float64 = (nf + 1.0) / 2.0

        var sumXY: Float64 = 0.0
        var sumX2: Float64 = 0.0
        var sumY2: Float64 = 0.0

        var i: Int32 = 0
        while (i < n) {
            let xi: Float64 = this.data.get(i)
            let yi: Float64 = ((i + 1) as Float64)
            let dx: Float64 = xi - meanX
            let dy: Float64 = yi - meanY
            sumXY = sumXY + dx * dy
            sumX2 = sumX2 + dx * dx
            sumY2 = sumY2 + dy * dy
            i = i + 1
        }

        if (sumX2 == 0.0 || sumY2 == 0.0) {
            return 0.0
        }

        let corr: Float64 = sumXY / sqrt(sumX2 * sumY2)
        return round(corr * 100.0) / 100.0
    }
}

