class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    // Helpers
    private func isLower(c: Rune): Bool {
        return c >= 'a' && c <= 'z'
    }

    private func isUpper(c: Rune): Bool {
        return c >= 'A' && c <= 'Z'
    }

    private func toLower(c: Rune): Rune {
        if (this.isUpper(c)) {
            return (c + ('a' - 'A')) as Rune
        }
        return c
    }

    private func mod(a: Int64, m: Int64): Int64 {
        var r = a % m
        if (r < 0) {
            r = r + m
        }
        return r
    }

    private func shiftRuneDecrypt(c: Rune, shift: Int64): Rune {
        if (this.isLower(c)) {
            let base: Rune = 'a'
            let offset: Int64 = ((c - base) as Int64)
            let n: Int64 = this.mod(offset - this.mod(shift, 26), 26)
            return (base + n) as Rune
        } else if (this.isUpper(c)) {
            let base: Rune = 'A'
            let offset: Int64 = ((c - base) as Int64)
            let n: Int64 = this.mod(offset - this.mod(shift, 26), 26)
            return (base + n) as Rune
        } else {
            return c
        }
    }

    private func shiftRuneEncrypt(c: Rune, shift: Int64): Rune {
        if (this.isLower(c)) {
            let base: Rune = 'a'
            let offset: Int64 = ((c - base) as Int64)
            let n: Int64 = this.mod(offset + this.mod(shift, 26), 26)
            return (base + n) as Rune
        } else if (this.isUpper(c)) {
            let base: Rune = 'A'
            let offset: Int64 = ((c - base) as Int64)
            let n: Int64 = this.mod(offset + this.mod(shift, 26), 26)
            return (base + n) as Rune
        } else {
            return c
        }
    }

    private func keyShiftAt(index: Int64): Int64 {
        // derive shift from key character (treat non-letters as zero shift)
        if (this.key == "") {
            return 0
        }
        let ki: Int64 = this.mod(index, this.key.size)
        let kc: Rune = this.key[ki]
        let lc: Rune = this.toLower(kc)
        if (lc >= 'a' && lc <= 'z') {
            return ((lc - 'a') as Int64)
        }
        return 0
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var result: String = ""
        var i: Int64 = 0
        while (i < ciphertext.size) {
            let ch: Rune = ciphertext[i]
            let dec: Rune = this.shiftRuneDecrypt(ch, shift)
            result = result + String(dec)
            i = i + 1
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var result: String = ""
        var i: Int64 = 0
        var j: Int64 = 0
        while (i < ciphertext.size) {
            let ch: Rune = ciphertext[i]
            if (this.isLower(ch) || this.isUpper(ch)) {
                let kshift: Int64 = this.keyShiftAt(j)
                let dec: Rune = this.shiftRuneDecrypt(ch, kshift)
                result = result + String(dec)
                j = j + 1
            } else {
                result = result + String(ch)
            }
            i = i + 1
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        if (rails <= 1 || encrypted_text.size <= 1) {
            return encrypted_text
        }

        let n: Int64 = encrypted_text.size

        // Step 1: build rail map for positions
        var railMap: ArrayList<Int64> = ArrayList<Int64>()
        railMap.ensureCapacity(n)
        var i: Int64 = 0
        while (i < n) {
            railMap.add(0)
            i = i + 1
        }

        var rail: Int64 = 0
        var dir: Int64 = 1
        i = 0
        while (i < n) {
            railMap.set(i, rail)
            if (rail == 0) {
                dir = 1
            } else if (rail == rails - 1) {
                dir = -1
            }
            rail = rail + dir
            i = i + 1
        }

        // Step 2: fill placeholder array for plaintext with '\0'
        var plain: ArrayList<Rune> = ArrayList<Rune>()
        plain.ensureCapacity(n)
        i = 0
        while (i < n) {
            plain.add('\0')
            i = i + 1
        }

        // Step 3: for each rail, assign characters from encrypted_text sequentially
        var idxCipher: Int64 = 0
        var r: Int64 = 0
        while (r < rails) {
            i = 0
            while (i < n && idxCipher < n) {
                if (railMap.get(i) == r) {
                    plain.set(i, encrypted_text[idxCipher])
                    idxCipher = idxCipher + 1
                }
                i = i + 1
            }
            r = r + 1
        }

        // Step 4: build result in natural order
        var result: String = ""
        i = 0
        while (i < n) {
            result = result + String(plain.get(i))
            i = i + 1
        }
        return result
    }
