    let path: ArrayList<String>

    public init(state: ArrayList<ArrayList<Int64>>, path: ArrayList<String>) {
        this.state = state
        this.path = path
    }
}

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        var i: Int64 = 0
        while i < state.size {
            let row = state[i]
            var j: Int64 = 0
            while j < row.size {
                if row[j] == 0 {
                    return (i, j)
                }
                j = j + 1
            }
            i = i + 1
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = this.clone_state(state)
        let (i, j) = this.find_blank(new_state)

        var ni: Int64 = i
        var nj: Int64 = j

        if direction == "up" {
            ni = i - 1
        } else if direction == "down" {
            ni = i + 1
        } else if direction == "left" {
            nj = j - 1
        } else if direction == "right" {
            nj = j + 1
        }

        if ni >= 0 && ni < new_state.size && nj >= 0 && nj < new_state[0].size {
            let tmp = new_state[ni][nj]
            new_state[ni][nj] = new_state[i][j]
            new_state[i][j] = tmp
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>([])
        let (i, j) = this.find_blank(state)

        if i > 0 {
            moves.append("up")
        }
        if i < 2 {
            moves.append("down")
        }
        if j > 0 {
            moves.append("left")
        }
        if j < 2 {
            moves.append("right")
        }
        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<Node>([])
        let visited = ArrayList<ArrayList<ArrayList<Int64>>>([])

        open_list.append(Node(this.clone_state(this.initial_state), ArrayList<String>([])))
        visited.append(this.clone_state(this.initial_state))

        var idx: Int64 = 0
        while idx < open_list.size {
            let node = open_list[idx]
            if this.states_equal(node.state, this.goal_state) {
                return node.path
            }

            let moves = this.get_possible_moves(node.state)
            var k: Int64 = 0
            while k < moves.size {
                let dir = moves[k]
                let new_state = this.move(node.state, dir)

                if !this.contains_state(visited, new_state) {
                    let new_path = this.clone_path(node.path)
                    new_path.append(dir)
                    open_list.append(Node(new_state, new_path))
                    visited.append(this.clone_state(new_state))
                }
                k = k + 1
            }
            idx = idx + 1
        }

        return ArrayList<String>([])
    }

    private func clone_state(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        let res = ArrayList<ArrayList<Int64>>([])
        var i: Int64 = 0
        while i < state.size {
            let row = state[i]
            let new_row = ArrayList<Int64>([])
            var j: Int64 = 0
            while j < row.size {
                new_row.append(row[j])
                j = j + 1
            }
            res.append(new_row)
            i = i + 1
        }
        return res
    }

    private func clone_path(path: ArrayList<String>): ArrayList<String> {
        let res = ArrayList<String>([])
        var i: Int64 = 0
        while i < path.size {
            res.append(path[i])
            i = i + 1
        }
        return res
    }

    private func states_equal(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        if a.size != b.size {
            return false
        }
        var i: Int64 = 0
        while i < a.size {
            if a[i].size != b[i].size {
                return false
            }
            var j: Int64 = 0
            while j < a[i].size {
                if a[i][j] != b[i][j] {
                    return false
                }
                j = j + 1
            }
            i = i + 1
        }
        return true
    }

    private func contains_state(list: ArrayList<ArrayList<ArrayList<Int64>>>, state: ArrayList<ArrayList<Int64>>): Bool {
        var i: Int64 = 0
        while i < list.size {
            if this.states_equal(list[i], state) {
                return true
            }
            i = i + 1
        }
        return false
    }
}

