import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    private func mod26(x: Int64): Int64 {
        var r = x % 26
        if (r < 0) {
            r = r + 26
        }
        return r
    }

    private func alphaIndexLower(b: Byte): Int64 {
        let alphaLower = "abcdefghijklmnopqrstuvwxyz"
        var j: Int64 = 0
        while (j < 26) {
            if (alphaLower[j] == b) {
                return j
            }
            j = j + 1
        }
        return -1
    }

    private func alphaIndexUpper(b: Byte): Int64 {
        let alphaUpper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        var j: Int64 = 0
        while (j < 26) {
            if (alphaUpper[j] == b) {
                return j
            }
            j = j + 1
        }
        return -1
    }

    private func getKeyShiftAt(pos: Int64): Int64 {
        let n: Int64 = this.key.length
        if (n == 0) {
            return 0
        }
        let alphaLower = "abcdefghijklmnopqrstuvwxyz"
        let alphaUpper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let kb: Byte = this.key[pos % n]
        var j: Int64 = 0
        while (j < 26) {
            if (alphaLower[j] == kb || alphaUpper[j] == kb) {
                return j
            }
            j = j + 1
        }
        return 0
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let alphaLower = "abcdefghijklmnopqrstuvwxyz"
        let alphaUpper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let n: Int64 = plaintext.length
        var res: String = ""
        let s: Int64 = this.mod26(shift)

        var i: Int64 = 0
        while (i < n) {
            let b: Byte = plaintext[i]
            var idx: Int64 = this.alphaIndexLower(b)
            if (idx != -1) {
                let ni: Int64 = this.mod26(idx + s)
                res = res + alphaLower[Range<Int64>(ni, ni + 1)]
            } else {
                idx = this.alphaIndexUpper(b)
                if (idx != -1) {
                    let ni: Int64 = this.mod26(idx + s)
                    res = res + alphaUpper[Range<Int64>(ni, ni + 1)]
                } else {
                    // Non-letter: keep as is (assumes ASCII single byte)
                    res = res + plaintext[Range<Int64>(i, i + 1)]
                }
            }
            i = i + 1
        }
        return res
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let alphaLower = "abcdefghijklmnopqrstuvwxyz"
        let alphaUpper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let n: Int64 = plain_text.length
        var res: String = ""

        var i: Int64 = 0
        var kpos: Int64 = 0
        while (i < n) {
            let b: Byte = plain_text[i]
            var idx: Int64 = this.alphaIndexLower(b)
            if (idx != -1) {
                let s: Int64 = this.getKeyShiftAt(kpos)
                let ni: Int64 = this.mod26(idx + s)
                res = res + alphaLower[Range<Int64>(ni, ni + 1)]
                kpos = kpos + 1
            } else {
                idx = this.alphaIndexUpper(b)
                if (idx != -1) {
                    let s: Int64 = this.getKeyShiftAt(kpos)
                    let ni: Int64 = this.mod26(idx + s)
                    res = res + alphaUpper[Range<Int64>(ni, ni + 1)]
                    kpos = kpos + 1
                } else {
                    // Non-letter: keep as is and do not advance key position
                    res = res + plain_text[Range<Int64>(i, i + 1)]
                }
            }
            i = i + 1
        }
        return res
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        let n: Int64 = plain_text.length
        if (rails <= 1 || rails >= n) {
            return plain_text
        }

        var rows = ArrayList<String>()
        var r: Int64 = 0
        while (r < rails) {
            rows.add("")
            r = r + 1
        }

        var row: Int64 = 0
        var dir: Int64 = 1  // 1: down, -1: up

        var i: Int64 = 0
        while (i < n) {
            let ch: String = plain_text[Range<Int64>(i, i + 1)]
            let cur: String = rows.get(row)
            rows.set(row, cur + ch)

            if (row == 0) {
                dir = 1
            } else if (row == rails - 1) {
                dir = -1
            }
            row = row + dir
            i = i + 1
        }

        var res: String = ""
        r = 0
        while (r < rails) {
            res = res + rows.get(r)
            r = r + 1
        }
        return res
    }
}

