import std.math.numeric.Decimal
import std.collection.ArrayList

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0
        */
        // Prepare (infix -> postfix)
        self.prepare(expression)

        let value_stack = ArrayList<Decimal>()

        var i: Int64 = 0
        while (i < postfix_stack.size) {
            let token = postfix_stack.get(i)
            if (ExpressionCalculator.is_operator(token)) {
                // operator: pop two values
                let rhs = value_stack.get(value_stack.size - 1)
                value_stack.removeAt(value_stack.size - 1)
                let lhs = value_stack.get(value_stack.size - 1)
                value_stack.removeAt(value_stack.size - 1)
                let res = ExpressionCalculator._calculate(lhs, rhs, token)
                value_stack.add(res)
            } else {
                // number
                let dv = Decimal(token)
                value_stack.add(dv)
            }
            i = i + 1
        }

        if (value_stack.size == 0) {
            return 0.0
        }
        let finalDecimal = value_stack.get(0)
        // Convert Decimal to Float64 via string (best-effort fallback)
        let s = "${finalDecimal}"
        return s.toFloat64()
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        // Clear previous
        while (postfix_stack.size > 0) {
            postfix_stack.removeAt(postfix_stack.size - 1)
        }

        let expr = ExpressionCalculator.transform(expression)
        let op_stack = ArrayList<String>()

        func precedence(op: String): Int64 {
            if (op == "+" || op == "-") { return 1 }
            if (op == "*" || op == "/" || op == "%") { return 2 }
            if (op == "(") { return 0 }
            return -1
        }

        var i: Int64 = 0
        let n = expr.length
        while (i < n) {
            let ch = expr.charAt(i)

            if ((ch >= "0" && ch <= "9") || ch == ".") {
                // parse number
                var num = ""
                while (i < n) {
                    let c = expr.charAt(i)
                    if ((c >= "0" && c <= "9") || c == ".") {
                        num = num + c
                        i = i + 1
                    } else {
                        break
                    }
                }
                postfix_stack.add(num)
                continue
            } else if (ch == "(") {
                op_stack.add(ch)
                i = i + 1
                continue
            } else if (ch == ")") {
                // Pop until "("
                while (op_stack.size > 0 && op_stack.get(op_stack.size - 1) != "(") {
                    let op = op_stack.get(op_stack.size - 1)
                    op_stack.removeAt(op_stack.size - 1)
                    postfix_stack.add(op)
                }
                if (op_stack.size > 0 && op_stack.get(op_stack.size - 1) == "(") {
                    op_stack.removeAt(op_stack.size - 1)
                }
                i = i + 1
                continue
            } else if (ExpressionCalculator.is_operator(ch)) {
                let cur = ch
                // Shunting-yard: pop while prec(peek) >= prec(cur)
                while (op_stack.size > 0) {
                    let top = op_stack.get(op_stack.size - 1)
                    if (top == "(") {
                        break
                    }
                    if (self.compare(top, cur)) {
                        let op = op_stack.get(op_stack.size - 1)
                        op_stack.removeAt(op_stack.size - 1)
                        postfix_stack.add(op)
                    } else {
                        break
                    }
                }
                op_stack.add(cur)
                i = i + 1
                continue
            } else {
                // Unknown character, skip
                i = i + 1
                continue
            }
        }

        // Drain op_stack
        while (op_stack.size > 0) {
            let op = op_stack.get(op_stack.size - 1)
            op_stack.removeAt(op_stack.size - 1)
            if (op != "(" && op != ")") {
                postfix_stack.add(op)
            }
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
