import std.collection.ArrayList

class Interpolation {

    private static func lowerIndex(arr: ArrayList<Float64>, value: Float64): Int64 {
        let n = arr.size()
        if n < 2 {
            return 0
        }
        if value <= arr.get(0) {
            return 0
        }
        if value >= arr.get(n - 1) {
            return n - 2
        }
        var lo: Int64 = 0
        var hi: Int64 = n - 1
        while lo + 1 < hi {
            let mid: Int64 = (lo + hi) / 2
            if value < arr.get(mid) {
                hi = mid
            } else {
                lo = mid
            }
        }
        return lo
    }

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size()
        let res = ArrayList<Float64>()
        if n < 2 || n != y.size() {
            return res
        }
        let m = x_interp.size()
        var i: Int64 = 0
        while i < m {
            let xi = x_interp.get(i)
            let j = Interpolation.lowerIndex(x, xi)
            let x1 = x.get(j)
            let x2 = x.get(j + 1)
            let y1 = y.get(j)
            let y2 = y.get(j + 1)
            let yi: Float64
            if x2 == x1 {
                yi = y1
            } else {
                yi = y1 + (y2 - y1) * (xi - x1) / (x2 - x1)
            }
            res.add(yi)
            i = i + 1
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size()
        let ny = y.size()
        let res = ArrayList<Float64>()
        if nx < 2 || ny < 2 {
            return res
        }
        // Basic shape checks (optional)
        if z.size() != nx {
            return res
        }
        var row: Int64 = 0
        while row < nx {
            if z.get(row).size() != ny {
                return res
            }
            row = row + 1
        }
        var m: Int64 = x_interp.size()
        if y_interp.size() < m {
            m = y_interp.size()
        }
        var i: Int64 = 0
        while i < m {
            let xi = x_interp.get(i)
            let yi = y_interp.get(i)

            let jx = Interpolation.lowerIndex(x, xi)
            let jy = Interpolation.lowerIndex(y, yi)

            let x1 = x.get(jx)
            let x2 = x.get(jx + 1)
            let y1 = y.get(jy)
            let y2 = y.get(jy + 1)

            let z11 = z.get(jx).get(jy)
            let z21 = z.get(jx + 1).get(jy)
            let z12 = z.get(jx).get(jy + 1)
            let z22 = z.get(jx + 1).get(jy + 1)

            let dx = x2 - x1
            let dy = y2 - y1
            let tx: Float64 = dx == 0.0 ? 0.0 : (xi - x1) / dx
            let ty: Float64 = dy == 0.0 ? 0.0 : (yi - y1) / dy

            let v = z11 * (1.0 - tx) * (1.0 - ty)
                  + z21 * tx * (1.0 - ty)
                  + z12 * (1.0 - tx) * ty
                  + z22 * tx * ty

            res.add(v)
            i = i + 1
        }
        return res
    }
}

