class Manacher {

    /*
    This is a class that implements a manacher algorithm to find the Longest palindromic substring in a given string.
    */

    let input_string: String

    public init(input_string: String) {
        /*
        Initializes the Manacher class with the given input_string.
        :param input_string: The input_string to be searched, String.
        */
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        /*
        Recursively calculates the length of the palindromic substring based on a given center, difference value, and input string.
        :param center: The center of the palindromic substring, Int64.
        :param diff: The difference between the center and the current position, Int64.
        :param string: The string to be searched, String.
        :return: The length of the palindromic substring, Int64.
        >>> manacher = Manacher("ababa")
        >>> manacher.palindromic_length(2, 1, "a|b|a|b|a")
        2

        */
        if (center - diff < 0) {
            return diff - 1
        }
        if (center + diff >= string.length()) {
            return diff - 1
        }
        if (string[center - diff] != string[center + diff]) {
            return diff - 1
        }
        return palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        >>> manacher = Manacher("ababaxse")
        >>> manacher.palindromic_string()
        "ababa"

        */
        let s = this.input_string
        if (s.length() == 0) {
            return ""
        }

        // transform: insert '|' between characters
        let t = transform_with_pipes(s)

        let n: Int64 = t.length()
        let zero: Int64 = 0
        let one: Int64 = 1

        let mutableBestCenter: Int64 = 0
        let mutableBestR: Int64 = 0

        let iStart: Int64 = 0
        let iEnd: Int64 = n

        let i: Int64 = iStart
        while (i < iEnd) {
            let r = palindromic_length(i, one, t)
            if (r > mutableBestR) {
                mutableBestR = r
                mutableBestCenter = i
            }
            i = i + 1
        }

        let L: Int64 = mutableBestCenter - mutableBestR
        let R: Int64 = mutableBestCenter + mutableBestR

        // map back to original indices
        // start index in original
        let start: Int64 = (L % 2 == 0) ? (L / 2) : ((L + 1) / 2)
        // end (exclusive) index in original
        let endExclusive: Int64 = (R / 2) + 1

        // build result substring
        let result: String = substring_range(s, start, endExclusive)
        return result
    }

    private func transform_with_pipes(s: String): String {
        let n: Int64 = s.length()
        if (n == 0) {
            return ""
        }
        let res: String = ""
        let i: Int64 = 0
        while (i < n) {
            // append current character
            res = res + s[i]
            // append pipe if not last character
            if (i != n - 1) {
                res = res + "|"
            }
            i = i + 1
        }
        return res
    }

    private func substring_range(s: String, start: Int64, endExclusive: Int64): String {
        // builds substring s[start .. endExclusive)
        let res: String = ""
        let i: Int64 = start
        while (i < endExclusive) {
            res = res + s[i]
            i = i + 1
        }
        return res
    }
}

