        }

        let denom: Int64 = tp + fp
        if (denom == 0) {
            return 0.0
        }
        return Float64(tp) / Float64(denom)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let nPred: Int64 = predicted_labels.size()
        let nTrue: Int64 = true_labels.size()
        if (nPred != nTrue) {
            throw IllegalArgumentException("predicted_labels and true_labels must have the same length")
        }

        var tp: Int64 = 0
        var fn: Int64 = 0

        var i: Int64 = 0
        while (i < nPred) {
            let p: Int64 = predicted_labels[i]
            let t: Int64 = true_labels[i]
            if (p == 1 && t == 1) {
                tp = tp + 1
            } else if (p == 0 && t == 1) {
                fn = fn + 1
            }
            i = i + 1
        }

        let denom: Int64 = tp + fn
        if (denom == 0) {
            return 0.0
        }
        return Float64(tp) / Float64(denom)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let p: Float64 = this.precision(predicted_labels, true_labels)
        let r: Float64 = this.recall(predicted_labels, true_labels)
        let s: Float64 = p + r
        if (s == 0.0) {
            return 0.0
        }
        return 2.0 * p * r / s
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let nPred: Int64 = predicted_labels.size()
        let nTrue: Int64 = true_labels.size()
        if (nPred != nTrue) {
            throw IllegalArgumentException("predicted_labels and true_labels must have the same length")
        }

        var correct: Int64 = 0

        var i: Int64 = 0
        while (i < nPred) {
            let p: Int64 = predicted_labels[i]
            let t: Int64 = true_labels[i]
            if (p == t) {
                correct = correct + 1
            }
            i = i + 1
        }

        if (nPred == 0) {
            return 0.0
        }
        return Float64(correct) / Float64(nPred)
    }
