import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        match (x) {
            case s: String => return format_string(s)
            case _ => return "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let normalized = normalize_number_string(x)
        if (normalized == "") {
            return "ZERO ONLY"
        }

        let parts = normalized.split(".")
        let intPart = parts[0]
        var result = format_integer_part(intPart)

        if (parts.size > 1) {
            let decPart = parts[1]
            let decWords = format_decimal_part(decPart)
            if (decWords != "") {
                if (result == "") {
                    result = "ZERO"
                }
                result = result + " POINT " + decWords
            }
        }

        if (result == "") {
            result = "ZERO"
        }
        return result + " ONLY"
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        if (s == "" || all_zero(s)) {
            return ""
        }
        // Ensure length two by padding
        var t = s
        if (t.length == 1) {
            t = "0" + t
        } else if (t.length > 2) {
            t = t.substring(t.length - 2, t.length)
        }

        let a = t.substring(0, 1)
        let b = t.substring(1, 2)
        let ai = digit_index(a)
        let bi = digit_index(b)

        if (ai == 0) {
            return NUMBER[bi]
        }
        if (ai == 1) {
            return NUMBER_TEEN[bi]
        }
        let tensWord = NUMBER_TEN[ai - 1]
        if (bi == 0) {
            return tensWord
        }
        return tensWord + " " + NUMBER[bi]
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        if (s == "" || all_zero(s)) {
            return ""
        }
        // Pad to three characters
        var t = s
        if (t.length == 1) {
            t = "00" + t
        } else if (t.length == 2) {
            t = "0" + t
        } else if (t.length > 3) {
            t = t.substring(t.length - 3, t.length)
        }

        let hStr = t.substring(0, 1)
        let tensStr = t.substring(1, 3)
        let hi = digit_index(hStr)

        if (hi == 0) {
            return trans_two(tensStr)
        }

        var res = NUMBER[hi] + " HUNDRED"
        let tail = trans_two(tensStr)
        if (tail != "") {
            res = res + " AND " + tail
        }
        return res
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i >= 0 && i < NUMBER_MORE.size.toInt64()) {
            return NUMBER_MORE[i.toInt32()]
        }
        return ""
    }

    // ----------------- Helpers -----------------

    private func format_integer_part(raw: String): String {
        var s = strip_leading_zeros(raw)
        if (s == "") {
            return ""
        }
        // Pad left to multiple of 3
        let len = s.length
        let mod = len % 3
        if (mod == 1) {
            s = "00" + s
        } else if (mod == 2) {
            s = "0" + s
        }

        let groups = s.length / 3
        var res = ""
        var j: Int32 = 0
        while (j < groups) {
            let start = j * 3
            let end = start + 3
            let group = s.substring(start, end)
            let words = trans_three(group)
            let suffixIndex = (groups - j - 1)
            if (words != "") {
                var piece = words
                if (suffixIndex > 0) {
                    piece = piece + " " + parse_more(suffixIndex.toInt64())
                }
                if (res == "") {
                    res = piece
                } else {
                    res = res + " " + piece
                }
            }
            j = j + 1
        }
        return res
    }

    private func format_decimal_part(dec: String): String {
        var d = dec
        if (d == "") {
            return ""
        }
        // Remove trailing spaces and non-digits
        d = filter_digits(d)
        if (d == "" || all_zero(d)) {
            return ""
        }
        var res = ""
        var i: Int32 = 0
        while (i < d.length) {
            let ch = d.substring(i, i + 1)
            let di = digit_index(ch)
            let w = NUMBER[di]
            if (w != "") {
                if (res == "") {
                    res = w
                } else {
                    res = res + " " + w
                }
            } else {
                // zero digit pronounced "ZERO" in decimals
                if (res == "") {
                    res = "ZERO"
                } else {
                    res = res + " ZERO"
                }
            }
            i = i + 1
        }
        return res
    }

    private func normalize_number_string(x: String): String {
        // Remove spaces and commas, keep digits and single dot
        var s = x.trim()
        s = s.replace(",", "")
        s = s.replace(" ", "")
        // Ensure only one dot
        let parts = s.split(".")
        if (parts.size == 0) {
            return ""
        } else if (parts.size == 1) {
            return filter_digits(parts[0])
        } else {
            let intPart = filter_digits(parts[0])
            let decPart = filter_digits(parts[1])
            if (decPart == "") {
                return intPart
            }
            return intPart + "." + decPart
        }
    }

    private func strip_leading_zeros(s: String): String {
        if (s == "") {
            return ""
        }
        var i: Int32 = 0
        while (i < s.length && s.substring(i, i + 1) == "0") {
            i = i + 1
        }
        if (i >= s.length) {
            return ""
        }
        return s.substring(i, s.length)
    }

    private func all_zero(s: String): Bool {
        if (s == "") {
            return true
        }
        var i: Int32 = 0
        while (i < s.length) {
            if (s.substring(i, i + 1) != "0") {
                return false
            }
            i = i + 1
        }
        return true
    }

    private func filter_digits(s: String): String {
        // Keep only '0'..'9'
        var out = ""
        var i: Int32 = 0
        while (i < s.length) {
            let ch = s.substring(i, i + 1)
            if (is_digit(ch)) {
                out = out + ch
            }
            i = i + 1
        }
        return out
    }

    private func is_digit(ch: String): Bool {
        return ch == "0" || ch == "1" || ch == "2" || ch == "3" || ch == "4" || ch == "5" || ch == "6" || ch == "7" || ch == "8" || ch == "9"
    }

    private func digit_index(ch: String): Int32 {
        if (ch == "0") { return 0 }
        if (ch == "1") { return 1 }
        if (ch == "2") { return 2 }
        if (ch == "3") { return 3 }
        if (ch == "4") { return 4 }
        if (ch == "5") { return 5 }
        if (ch == "6") { return 6 }
        if (ch == "7") { return 7 }
        if (ch == "8") { return 8 }
        if (ch == "9") { return 9 }
        return 0
    }
}

