import std.collection.ArrayList
import std.convert.RadixConvertible
import std.regex.*
import std.convert.*

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        var result: String = string

        /* Replace hex numeric entities: &#xHHHH; or &#XHHHH; */
        let rHex = Regex(#"&#[xX]([0-9A-Fa-f]+);"#)
        for (md in rHex.lazyFindAll(result, group: true)) {
            let hexDigits: String = md.matchString(1)
            let lit: String = "'\\u{" + hexDigits + "}'"
            match (Rune.tryParse(lit)) {
                case Some(ch) =>
                    let entity: String = md.matchString()
                    result = Regex(entity).replaceAll(result, ch.toString())
                case None => ()
            }
        }

        /* Replace decimal numeric entities: &#DDDD; */
        let rDec = Regex(#"&#(\d+);"#)
        for (md in rDec.lazyFindAll(result, group: true)) {
            let decDigits: String = md.matchString(1)
            var ok: Bool = true
            var value: Int64 = 0
            for (c in decDigits) {
                if (!c.isAsciiNumber()) {
                    ok = false
                    break
                }
                value = value * 10 + (c.position() - r'0'.position())
            }
            if (!ok) {
                continue
            }
            if (value < 0 || value > 1114111) {
                continue
            }
            let hexStr: String = NumericEntityUnescaper.toHex(value)
            let lit: String = "'\\u{" + hexStr + "}'"
            match (Rune.tryParse(lit)) {
                case Some(ch) =>
                    let entity: String = md.matchString()
                    result = Regex(entity).replaceAll(result, ch.toString())
                case None => ()
            }
        }

        return result
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isAsciiHex()
    }

    private static func toHex(n: Int64): String {
        if (n == 0) {
            return "0"
        }
        var value: Int64 = n
        var res: String = ""
        while (value > 0) {
            let d: Int64 = value % 16
            var ch: Rune
            if (d < 10) {
                ch = r'0'.next(d)
            } else {
                ch = r'a'.next(d - 10)
            }
            res = ch.toString() + res
            value = value / 16
        }
        return res
    }
}

