import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        /*
        Initialize the push box game with the map and various attributes.
        :param map: ArrayList<ArrayList<String>>, the map of the push box game, represented as a list of strings. 
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])
        >>> game = PushBoxGame(map) 
        */
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            /*
            Initialize the game by setting the positions of the player, targets, and boxes based on the map.
            >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
            >>> game.targets
            [[3, 3]]
            >>> game.boxes
            [[2, 2]]
            >>> game.player_row
            1
            >>> game.player_col
            1
            */
            var r: Int64 = 0
            while (r < this.map.size) {
                let row = this.map[r]
                var c: Int64 = 0
                while (c < row.size) {
                    let cell = row[c]
                    if (cell == "#") {
                        // wall, do nothing
                    } else if (cell == "O") {
                        this.player_row = r
                        this.player_col = c
                        // sanitize base map to keep only static tiles
                        row[c] = " "
                    } else if (cell == "G") {
                        let pos = ArrayList<Int64>([r, c])
                        this.targets.add(pos)
                    } else if (cell == "X") {
                        let boxPos = ArrayList<Int64>([r, c])
                        this.boxes.add(boxPos)
                        // sanitize base map
                        row[c] = " "
                    } else {
                        // empty space
                    }
                    c++
                }
                r++
            }
            this.target_count = this.targets.size
            this.is_game_over = false
        }
        init_game()
    }

    func indexOfPosition(list: ArrayList<ArrayList<Int64>>, row: Int64, col: Int64): Int64 {
        var i: Int64 = 0
        while (i < list.size) {
            let pos = list[i]
            if (pos[0] == row && pos[1] == col) {
                return i
            }
            i++
        }
        return -1
    }

    public func check_win(): Bool {
        /*
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of this.is_game_over.
        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        var covered: Int64 = 0
        var i: Int64 = 0
        while (i < this.targets.size) {
            let t = this.targets[i]
            if (indexOfPosition(this.boxes, t[0], t[1]) >= 0) {
                covered++
            }
            i++
        }
        this.is_game_over = (covered == this.target_count)
        return this.is_game_over
    }

    func is_wall(row: Int64, col: Int64): Bool {
        if (row < 0 || col < 0) {
            return true
        }
        if (row >= this.map.size) {
            return true
        }
        let width = this.map[0].size
        if (col >= width) {
            return true
        }
        return this.map[row][col] == "#"
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        if (this.is_game_over) {
            return true
        }

        var dr: Int64 = 0
        var dc: Int64 = 0
        if (direction == "w") {
            dr = -1
            dc = 0
        } else if (direction == "s") {
            dr = 1
            dc = 0
        } else if (direction == "a") {
            dr = 0
            dc = -1
        } else if (direction == "d") {
            dr = 0
            dc = 1
        } else {
            return this.check_win()
        }

        let nr = this.player_row + dr
        let nc = this.player_col + dc

        if (is_wall(nr, nc)) {
            return this.check_win()
        }

        // Check if next is a box
        let boxIdx = indexOfPosition(this.boxes, nr, nc)
        if (boxIdx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            // Cannot push into wall or outside or another box
            if (is_wall(br, bc)) {
                return this.check_win()
            }
            if (indexOfPosition(this.boxes, br, bc) >= 0) {
                return this.check_win()
            }
            // Push the box
            let pos = this.boxes[boxIdx]
            pos[0] = br
            pos[1] = bc
            // Move player into box's previous cell
            this.player_row = nr
            this.player_col = nc
        } else {
            // Move player into empty/target cell
            this.player_row = nr
            this.player_col = nc
        }

        return this.check_win()
    }

    public func print_map(): Unit {
        var r: Int64 = 0
        while (r < this.map.size) {
            let row = this.map[r]
            var c: Int64 = 0
            var line: String = ""
            while (c < row.size) {
                var ch = row[c]
                // Overlay player
                if (this.player_row == r && this.player_col == c) {
                    ch = "O"
                } else {
                    // Overlay box
                    if (indexOfPosition(this.boxes, r, c) >= 0) {
                        ch = "X"
                    } else {
                        // sanitize any base 'O'/'X' if present
                        if (ch == "O" || ch == "X") {
                            ch = " "
                        }
                    }
                }
                line = line + ch + " "
                c++
            }
            println(line)
            r++
        }
    }
}

main() {
    let map = ArrayList<ArrayList<String>>([
        ArrayList<String>(["#", "#", "#", "#", "#"]),
        ArrayList<String>(["#", "O", " ", " ", "#"]),
        ArrayList<String>(["#", " ", "X", " ", "#"]),
        ArrayList<String>(["#", " ", " ", "G", "#"]),
        ArrayList<String>(["#", "#", "#", "#", "#"])
    ])
    let game = PushBoxGame(map)
    game.print_map()
    println(game.move("d"))
    println(game.move("s"))
    println(game.move("a"))
    println(game.move("s"))
    println(game.move("d"))
}

