        } else {
            return this.check_win()
        }

        let nr = this.player_row + dr
        let nc = this.player_col + dc

        if (is_wall(nr, nc)) {
            return this.check_win()
        }

        // Check if next is a box
        let boxIdx = indexOfPosition(this.boxes, nr, nc)
        if (boxIdx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            // Cannot push into wall or outside or another box
            if (is_wall(br, bc)) {
                return this.check_win()
            }
            if (indexOfPosition(this.boxes, br, bc) >= 0) {
                return this.check_win()
            }
            // Push the box
            let pos = this.boxes[boxIdx]
            pos[0] = br
            pos[1] = bc
            // Move player into box's previous cell
            this.player_row = nr
            this.player_col = nc
        } else {
            // Move player into empty/target cell
            this.player_row = nr
            this.player_col = nc
        }

        return this.check_win()
    }

    public func print_map(): Unit {
        var r: Int64 = 0
        while (r < this.map.size) {
            let row = this.map[r]
            var c: Int64 = 0
            var line: String = ""
            while (c < row.size) {
                var ch = row[c]
                // Overlay player
                if (this.player_row == r && this.player_col == c) {
                    ch = "O"
                } else {
                    // Overlay box
                    if (indexOfPosition(this.boxes, r, c) >= 0) {
                        ch = "X"
                    } else {
                        // sanitize any base 'O'/'X' if present
                        if (ch == "O" || ch == "X") {
                            ch = " "
                        }
                    }
                }
                line = line + ch + " "
                c++
            }
            println(line)
            r++
        }
    }
}

main() {
    let map = ArrayList<ArrayList<String>>([
        ArrayList<String>(["#", "#", "#", "#", "#"]),
        ArrayList<String>(["#", "O", " ", " ", "#"]),
        ArrayList<String>(["#", " ", "X", " ", "#"]),
        ArrayList<String>(["#", " ", " ", "G", "#"]),
        ArrayList<String>(["#", "#", "#", "#", "#"])
    ])
    let game = PushBoxGame(map)
    game.print_map()
    println(game.move("d"))
    println(game.move("s"))
    println(game.move("a"))
    println(game.move("s"))
    println(game.move("d"))
}
