import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    /*
    The class allows to split sentences, count words in a sentence, and process a text file to find the maximum word count.
    */

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let res = ArrayList<String>()
        let r = Regex(##"(.*?(?:\.(?=\s)(?<!Mr\.)|\?(?=\s)|\.$|\?$))"##)
        for (md in r.lazyFindAll(sentences_string)) {
            res.add(md.matchString())
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
        var cnt: Int64 = 0
        let splitRegex = Regex("\\s+")
        let wordRegex = Regex("^[A-Za-z]+$")
        for (token in splitRegex.split(sentence)) {
            match (wordRegex.find(token)) {
                case Some(_) => cnt += 1
                case None => ()
            }
        }
        return cnt
    }

    public func process_text_file(sentences_string: String): Int64 {
        var maxCnt: Int64 = 0
        let sentences = this.split_sentences(sentences_string)
        for (s in sentences) {
            let c = this.count_words(s)
            if (c > maxCnt) {
                maxCnt = c
            }
        }
        return maxCnt
    }
}

