import std.collection.ArrayList

class Option<T> {
    let value: ?T

    private init(value: ?T) {
        this.value = value
    }

    public static func some(value: T): Option<T> {
        return Option<T>(value: value)
    }

    public static func none(): Option<T> {
        return Option<T>(value: null)
    }
}

class TicTacToe {

    /*
    The class represents a game of Tic-Tac-Toe and its functions include making a move on the board, checking for a winner, and determining if the board is full.
    */

    let board: ArrayList<ArrayList<String>>
    var current_player: String
    let n: Int64

    public init(N!: Int64 = 3) {
        /*
        Initialize a 3x3 game board with all empty spaces and current symble player, default is 'X'.
        */
        this.n = N
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Place the current player's mark at the specified position on the board and switch the mark.
        :param row: Int64, the row index of the position
        :param col: Int64, the column index of the position
        :return: Bool, indicating whether the move was successful or not
        >>> ttt.current_player
        'X'
        >>> ttt.make_move(1, 1)
        >>> ttt.current_player
        'O'
        */
        if (row < 0 || row >= this.n || col < 0 || col >= this.n) {
            return false
        }
        let r = this.board[row]
        if (r[col] != " ") {
            return false
        }
        r[col] = this.current_player
        if (this.current_player == "X") {
            this.current_player = "O"
        } else {
            this.current_player = "X"
        }
        return true
    }

    public func check_winner(): Option<String> {
        /*
        Check if there is a winner on the board in rows, columns and diagonals three directions
        :return: Option<String>, the mark of the winner ('X' or 'O'), or None if there is no winner yet
        >>> moves = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 0]), ArrayList<Int64>([2, 0]), ArrayList<Int64>([1, 1]), ArrayList<Int64>([2, 1]), ArrayList<Int64>([1, 2])])
        >>> for move in moves:
        ...     ttt.make_move(move[0], move[1])
        >>> ttt.check_winner()
        'X'
        */
        // Check rows
        for (i in 0..this.n) {
            let first = this.board[i][0]
            if (first != " ") {
                var win = true
                for (j in 1..this.n) {
                    if (this.board[i][j] != first) {
                        win = false
                        break
                    }
                }
                if (win) {
                    return Option<String>.some(value: first)
                }
            }
        }
        // Check columns
        for (j in 0..this.n) {
            let first = this.board[0][j]
            if (first != " ") {
                var win = true
                for (i in 1..this.n) {
                    if (this.board[i][j] != first) {
                        win = false
                        break
                    }
                }
                if (win) {
                    return Option<String>.some(value: first)
                }
            }
        }
        // Check main diagonal
        var diagFirst = this.board[0][0]
        if (diagFirst != " ") {
            var winMain = true
            for (k in 1..this.n) {
                if (this.board[k][k] != diagFirst) {
                    winMain = false
                    break
                }
            }
            if (winMain) {
                return Option<String>.some(value: diagFirst)
            }
        }
        // Check anti-diagonal
        let lastIdx = this.n - 1
        diagFirst = this.board[0][lastIdx]
        if (diagFirst != " ") {
            var winAnti = true
            for (k in 1..this.n) {
                if (this.board[k][lastIdx - k] != diagFirst) {
                    winAnti = false
                    break
                }
            }
            if (winAnti) {
                return Option<String>.some(value: diagFirst)
            }
        }
        return Option<String>.none()
    }

    public func is_board_full(): Bool {
        /*
        Check if the game board is completely filled.
        :return: Bool, indicating whether the game board is full or not
        >>> ttt.is_board_full()
        false
        */
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (this.board[i][j] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

