import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let idx: Int64 = this.url.indexOf("://")
        if idx < 0 {
            return Option.None
        }
        let scheme: String = this.url.substring(0, idx)
        if scheme.length() == 0 {
            return Option.None
        }
        return Option.Some(scheme)
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let schemeIdx: Int64 = this.url.indexOf("://")
        var start: Int64 = 0
        if schemeIdx >= 0 {
            start = schemeIdx + 3
        } else {
            // try scheme-less URL, optionally starting with //
            if this.url.length() >= 2 && this.url.substring(0, 2) == "//" {
                start = 2
            } else {
                start = 0
            }
        }
        if start >= this.url.length() {
            return Option.None
        }
        let slashIdx: Int64 = this.url.indexOf("/", start)
        let qIdx: Int64 = this.url.indexOf("?", start)
        let fragIdx: Int64 = this.url.indexOf("#", start)

        // choose smallest non-negative index among slashIdx, qIdx, fragIdx
        var end: Int64 = this.url.length()
        if slashIdx >= 0 && slashIdx < end { end = slashIdx }
        if qIdx >= 0 && qIdx < end { end = qIdx }
        if fragIdx >= 0 && fragIdx < end { end = fragIdx }

        if end <= start {
            return Option.None
        }

        let host: String = this.url.substring(start, end)
        if host.length() == 0 {
            return Option.None
        }
        return Option.Some(host)
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let schemeIdx: Int64 = this.url.indexOf("://")
        var startAfterHost: Int64 = 0
        if schemeIdx >= 0 {
            startAfterHost = schemeIdx + 3
        } else if this.url.length() >= 2 && this.url.substring(0, 2) == "//" {
            startAfterHost = 2
        } else {
            startAfterHost = 0
        }

        // find first slash after host
        let firstSlash: Int64 = this.url.indexOf("/", startAfterHost)
        if firstSlash < 0 {
            // no slash; treat as no path
            return Option.None
        }
        let path: String = this.url.substring(firstSlash)
        if path.length() == 0 {
            return Option.None
        }
        return Option.Some(path)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let qIdx: Int64 = this.url.indexOf("?")
        if qIdx < 0 {
            return Option.None
        }
        // query ends at '#' or end
        let fragIdx: Int64 = this.url.indexOf("#", qIdx + 1)
        var end: Int64 = this.url.length()
        if fragIdx >= 0 {
            end = fragIdx
        }
        if qIdx + 1 >= end {
            // empty query string
            return Option.Some(HashMap<String, String>())
        }

        let query: String = this.url.substring(qIdx + 1, end)
        let pairs: Array<String> = query.split("&")
        let map: HashMap<String, String> = HashMap<String, String>()
        for pair in pairs {
            if pair.length() == 0 {
                continue
            }
            let eqIdx: Int64 = pair.indexOf("=")
            if eqIdx < 0 {
                // key with empty value
                let key: String = pair
                map.put(key, "")
            } else {
                let key: String = pair.substring(0, eqIdx)
                let value: String = pair.substring(eqIdx + 1)
                map.put(key, value)
            }
        }
        return Option.Some(map)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragIdx: Int64 = this.url.indexOf("#")
        if fragIdx < 0 {
            return Option.None
        }
        if fragIdx + 1 > this.url.length() {
            return Option.None
        }
        let fragment: String = this.url.substring(fragIdx + 1)
        if fragment.length() == 0 {
            return Option.None
        }
        return Option.Some(fragment)
    }
}

