        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        let fixed = UrlPath.fix_path(segment)
        if (fixed.length() == 0) {
            return
        }
        let parts = fixed.split("/")
        for part in parts {
            if (!part.isEmpty()) {
                this.segments.add(part)
            }
        }
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.clear()
        this.with_end_tag = (path.length() > 0) && path.endsWith("/")
        let fixed = UrlPath.fix_path(path)
        if (fixed.length() == 0) {
            return
        }
        let parts = fixed.split("/")
        for part in parts {
            if (!part.isEmpty()) {
                this.segments.add(part)
            }
        }
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        if (path.length() == 0) {
            return path
        }
        var start = 0
        var end = path.length()
        while (start < end && path.substring(start, start + 1) == "/") {
            start = start + 1
        }
        while (end > start && path.substring(end - 1, end) == "/") {
            end = end - 1
        }
        if (start >= end) {
            return ""
        }
        return path.substring(start, end)
    }
}
