import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    /*
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    */

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let len: Int64 = vector_1.size
        var dot: Float64 = 0.0
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0
        for i in 0..len {
            let v1: Float64 = vector_1[i]
            let v2: Float64 = vector_2[i]
            dot += v1 * v2
            norm1 += v1 * v1
            norm2 += v2 * v2
        }
        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }
        return dot / sqrt(norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let n: Int64 = vectors_all.size
        let out: ArrayList<Float64> = ArrayList<Float64>(n, repeat: 0.0)
        for i in 0..n {
            let v: ArrayList<Float64> = vectors_all[i]
            out[i] = VectorUtil.similarity(vector_1, v)
        }
        return out
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let n1: Int64 = vector_list_1.size
        let n2: Int64 = vector_list_2.size
        if n1 == 0 || n2 == 0 {
            return 0.0
        }
        let dim: Int64 = vector_list_1[0].size

        let sum1: ArrayList<Float64> = ArrayList<Float64>(dim, repeat: 0.0)
        for i in 0..n1 {
            let v: ArrayList<Float64> = vector_list_1[i]
            for d in 0..dim {
                sum1[d] = sum1[d] + v[d]
            }
        }
        let avg1: ArrayList<Float64> = ArrayList<Float64>(dim, repeat: 0.0)
        let invN1: Float64 = 1.0 / Float64(n1)
        for d in 0..dim {
            avg1[d] = sum1[d] * invN1
        }

        let sum2: ArrayList<Float64> = ArrayList<Float64>(dim, repeat: 0.0)
        for i in 0..n2 {
            let v: ArrayList<Float64> = vector_list_2[i]
            for d in 0..dim {
                sum2[d] = sum2[d] + v[d]
            }
        }
        let avg2: ArrayList<Float64> = ArrayList<Float64>(dim, repeat: 0.0)
        let invN2: Float64 = 1.0 / Float64(n2)
        for d in 0..dim {
            avg2[d] = sum2[d] * invN2
        }

        return VectorUtil.similarity(avg1, avg2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result: HashMap<String, Float64> = HashMap<String, Float64>()
        let tn: Float64 = Float64(total_num) + 1.0
        for (k, c) in number_dict {
            let idf: Float64 = log(tn / (c + 1.0))
            result.add(k, idf)
        }
        return result
    }
}

